"""Take plans -> jobs/*.json (generated by pt_gen.py; a take that exists is never paid twice).
  python pt_jobs.py narr        James / eleven_v4: 9 chunks x 4 takes, neighbouring script lines as previous / next text
  python pt_jobs.py cast        auditions: every candidate's own lines, 3-4 takes per candidate
  python pt_jobs.py chars D=kei T=gus KID=piku      the final cast: 4+ takes per character line (one line per take)
Settings = the clown v6 / v6b ones the owner loved: eleven_v4, similarity 0.75, stability 0.5 / 0.35, speed 1.0
(v4 ignores speed), one short tag per sentence at most (LESSONS 3, 36)."""
import json
import sys

import pt_lib as L

T = L.TEXT
J = L.JAMES


def ctx(ids):
    return " ".join(T[i] for i in ids) or None


def check(lines, text):
    d = L.word_diff(" ".join(T[i] for i in lines), text)
    assert d == [], (lines, text, d)


