ROLE_OF = {"d01": "D", "d02": "D", "d03": "D", "d04": "D", "t01": "T", "t02": "T", "t03": "T", "t04": "T", "t05": "T", "t06": "T", "k01": "KID"}


def narr():
    jobs = []
    for ci, (c, (lines, prev, nxt, takes)) in enumerate(NARR.items()):
        for t, text, stab in takes:
            check(lines, text)
            jobs.append({"folder": c, "take": t, "voice": J, "model": L.MODEL, "text": text, "stability": stab, "speed": 1.0,
                         "seed": 7000 + 10 * ci + int(t[1:]), "prev": ctx(prev), "next": ctx(nxt), "lines": lines, "role": "N", "candidate": "james"})
    return jobs


def cast():
    jobs = []
    for ri, (role, specs) in enumerate(CAST.items()):
        for si, (folder, lines, prev, nxt, takes) in enumerate(specs):
            for ci, (cand, vid) in enumerate(CAND[role]):
                for suf, text, stab in takes:
                    check(lines, text)
                    jobs.append({"folder": folder, "take": f"{cand}{suf}", "voice": vid, "model": L.MODEL, "text": text, "stability": stab,
                                 "speed": 1.0, "seed": 8000 + 100 * ri + 30 * si + 3 * ci + int(suf), "prev": ctx(prev), "next": ctx(nxt),
                                 "lines": lines, "role": role, "candidate": cand})
    return jobs


def chars(win):
    jobs = []
    for li, (lid, (prev, nxt, takes)) in enumerate(CHAR.items()):
        role = ROLE_OF[lid]
        if role not in win:
            continue
        vid = dict(CAND[role])[win[role]]
        for t, text, stab in takes:
            check([lid], text)
            jobs.append({"folder": f"ch_{lid}", "take": t, "voice": vid, "model": L.MODEL, "text": text, "stability": stab, "speed": 1.0,
                         "seed": 8600 + 10 * li + int(t[1:]), "prev": ctx(prev), "next": ctx(nxt), "lines": [lid], "role": role, "candidate": win[role]})
    return jobs


if __name__ == "__main__":
    what = sys.argv[1]
    (L.HERE / "jobs").mkdir(exist_ok=True)
    if what == "narr":
        jobs = narr()
    elif what == "cast":
        jobs = cast()
    else:
        jobs = chars(dict(a.split("=") for a in sys.argv[2:]))
    (L.HERE / "jobs" / f"{what}.json").write_text(json.dumps(jobs, ensure_ascii=False, indent=1), encoding="utf-8")
    print(what, len(jobs), "jobs,", sum(len(j["text"]) for j in jobs), "characters")
